def with_mweb_vbparams(args):
    """Return node extra_args with MWEB versionbits activation enabled."""
    if args is None:
        return [MWEB_VBPARAMS]
    return [MWEB_VBPARAMS, *args]


def with_assumeutxo_mweb_vbparams(args):
    """Return node extra_args for post-299 MWEB extension on the assumeutxo chain."""
    if args is None:
        return [ASSUMEUTXO_MWEB_VBPARAMS]
    return [ASSUMEUTXO_MWEB_VBPARAMS, *args]


def mweb_extra_args(*node_arg_lists):
    """Build per-node extra_args with MWEB activation for functional tests."""
    return [with_mweb_vbparams(args) for args in node_arg_lists]


def reconnect_mweb_peers(test):
    """Reconnect all nodes so VERSION handshakes include NODE_MWEB after pre-activation."""
    num_nodes = len(test.nodes)
    for i in range(num_nodes):
        for j in range(i + 1, num_nodes):
            try:
                test.disconnect_nodes(i, j)
            except Exception:
                pass
    for i in range(num_nodes):
        for j in range(i + 1, num_nodes):
            test.connect_nodes(i, j)
    test.wait_until(lambda: all(len(n.getpeerinfo()) > 0 for n in test.nodes), timeout=30)


def init_mweb_wallet(test, *, node):
    """Initialize a descriptor wallet for MWEB functional tests."""
    wallet_name = test.default_wallet_name if test.wallet_names is None else test.wallet_names[node] if node < len(test.wallet_names) else False
    if wallet_name is not False:
        n = test.nodes[node]
        if wallet_name is not None:
            n.createwallet(wallet_name=wallet_name, load_on_startup=True)
        wallet_importprivkey(n.get_wallet_rpc(wallet_name), n.get_deterministic_priv_key().key, 0, label="coinbase")


def init_named_assumeutxo_mweb_wallet(test, *, node, wallet_name, hdkey_tprv=ASSUMEUTXO_MWEB_HDKEY_TPRV, import_coinbase=True):
    """Initialize a descriptor MWEB wallet for AssumeUTXO tests."""
    from test_framework.util import JSONRPCException

    n = test.nodes[node]
    try:
        n.createwallet(wallet_name=wallet_name, blank=True, load_on_startup=True)
    except JSONRPCException as e:
        if e.error['code'] == -4:
            if wallet_name not in n.listwallets():
                n.loadwallet(wallet_name)
        elif e.error['code'] != -35:
            raise
    wallet = n.get_wallet_rpc(wallet_name)
    if not get_mweb_descriptor_entries(wallet)['external']:
        if hdkey_tprv is None:
            xpub = wallet.addhdkey()['xpub']
        else:
            xpub = wallet.addhdkey(hdkey_tprv)['xpub']
        wallet.createwalletdescriptor('bech32', {'hdkey': xpub})
        wallet.createwalletdescriptor('mweb', {'hdkey': xpub})
    if import_coinbase:
        wallet_importprivkey(wallet, n.get_deterministic_priv_key().key, 0, label="coinbase")
    return wallet


def init_assumeutxo_mweb_wallet(test, *, node):
    """Initialize a deterministic descriptor wallet for AssumeUTXO MWEB tests."""
    return init_named_assumeutxo_mweb_wallet(
        test,
        node=node,
        wallet_name=ASSUMEUTXO_MWEB_WALLET_NAME,
        hdkey_tprv=ASSUMEUTXO_MWEB_HDKEY_TPRV,
        import_coinbase=True,
    )


def _assumeutxo_wallet_rpc(test, node):
    n = test.nodes[node] if isinstance(node, int) else node
    return n.get_wallet_rpc(ASSUMEUTXO_MWEB_WALLET_NAME)


def _coinbase_outpoint(node, height):
    blockhash = node.getblockhash(height)
    coinbase_txid = node.getblock(blockhash)['tx'][0]
    return {"txid": coinbase_txid, "vout": 0}


def sendtoaddress_fixed_utxo(test, node, fund_height, amount=ASSUMEUTXO_MWEB_PEGIN_AMOUNT):
    """sendtoaddress spending a specific coinbase output (deterministic coin selection)."""
    wallet = _assumeutxo_wallet_rpc(test, node)
    outpoint = _coinbase_outpoint(node, fund_height)
    spendable = wallet.listunspent(minconf=1)
    lock = [
        {"txid": u['txid'], "vout": u['vout']}
        for u in spendable
        if u['txid'] != outpoint['txid'] or u['vout'] != outpoint['vout']
    ]
    if lock:
        assert wallet.lockunspent(False, lock)
    try:
        return wallet.sendtoaddress(ASSUMEUTXO_MWEB_PEGIN_ADDRESS, amount)
    finally:
        if lock:
            wallet.lockunspent(True, lock)


def generate_deterministic_blocks(test, node, nblocks, *, sync_fun=None):
    """Mine nblocks one at a time (feature_assumeutxo.py pattern)."""
    sync = sync_fun if sync_fun is not None else test.sync_all
    for _ in range(nblocks):
        test.generate(node, 1, sync_fun=test.no_op)
    sync()


def broadcast_assumeutxo_pegin(test, node, *, sync_fun=None):
    """Submit the hardcoded pegin at height 719 and mine block 720 (first MWEB block)."""
    from test_framework.util import assert_equal

    sync = sync_fun if sync_fun is not None else test.sync_all

    assert_equal(node.getblockcount(), ASSUMEUTXO_FIRST_MWEB_HEIGHT - 1)

    accept = node.testmempoolaccept([ASSUMEUTXO_MWEB_PEGIN_RAW_HEX])
    assert accept[0]['allowed'], accept[0].get('reject-reason', accept[0])

    pegin_txid = node.sendrawtransaction(ASSUMEUTXO_MWEB_PEGIN_RAW_HEX)
    assert_equal(pegin_txid, ASSUMEUTXO_MWEB_PEGIN_TXID)
    sync()
    assert_equal(set(node.getrawmempool()), {pegin_txid})

    generate_deterministic_blocks(test, node, 1, sync_fun=sync)
    block = node.getblock(node.getblockhash(ASSUMEUTXO_FIRST_MWEB_HEIGHT))
    assert_equal(ASSUMEUTXO_MWEB_PEGIN_TXID in block['tx'], True)
    return pegin_txid


def finish_assumeutxo_mweb_chain(test, node, *, sync_fun=None, capture_pegin=False):
    """Continue from the current tip through MWEB activation to SNAPSHOT_BASE_MWEB.

    Requires MWEB versionbits enabled, init_assumeutxo_mweb_wallet(), and a tip at
    or above ASSUMEUTXO_BASE_HEIGHT (299). feature_assumeutxo.py mines through
    height 399 with MWEB enabled, then calls this again after the upstream
    scenarios to reach height 750.
    """
    from test_framework.util import assert_equal

    sync = sync_fun if sync_fun is not None else test.sync_all

    assert ASSUMEUTXO_MWEB_PEGIN_ADDRESS.startswith('bcrt1m')
    tip = node.getblockcount()
    assert tip >= ASSUMEUTXO_BASE_HEIGHT

    pre_pegin_height = ASSUMEUTXO_FIRST_MWEB_HEIGHT - 1
    if tip < pre_pegin_height:
        if tip == ASSUMEUTXO_BASE_HEIGHT:
            node.setmocktime(MWEB_VB_START_TIME)
        generate_deterministic_blocks(test, node, pre_pegin_height - tip, sync_fun=sync)

    if capture_pegin:
        pegin_txid = sendtoaddress_fixed_utxo(test, node, ASSUMEUTXO_MWEB_PEGIN_FUND_HEIGHT)
        sync()
        raw_hex = _assumeutxo_wallet_rpc(test, node).gettransaction(pegin_txid)['hex']
        return pegin_txid, raw_hex

    pegin_txid = broadcast_assumeutxo_pegin(test, node, sync_fun=sync)

    remaining = SNAPSHOT_BASE_MWEB - node.getblockcount()
    generate_deterministic_blocks(test, node, remaining, sync_fun=sync)
    assert_equal(node.getblockcount(), SNAPSHOT_BASE_MWEB)


def build_assumeutxo_mweb_chain(test, node, *, sync_fun=None, capture_pegin=False):
    """Extend the upstream assumeutxo chain from height 299 to SNAPSHOT_BASE_MWEB.

    Used by mweb_generate_assumeutxo_hashes.py. feature_assumeutxo.py builds the
    base chain and post-299 blocks itself, then calls finish_assumeutxo_mweb_chain().
    """
    from test_framework.util import assert_equal

    assert_equal(node.getblockcount(), ASSUMEUTXO_BASE_HEIGHT)
    node.setmocktime(MWEB_VB_START_TIME)
    return finish_assumeutxo_mweb_chain(test, node, sync_fun=sync_fun, capture_pegin=capture_pegin)


