def is_mweb_account_desc_body(body):
    """True for ranged LIP-0008 account form mweb(scan,spend,*)."""
    return body.startswith('mweb(') and body.endswith(',*)')


def is_mweb_internal_desc_body(body):
    """True for wallet-internal mweb(A_i,B_i,i,acct_cksum)."""
    return body.startswith('mweb(') and body.count(',') == 3


def _mweb_desc_parts(body):
    """Return comma-separated args inside mweb(...), without the trailing ')'."""
    return body[body.index('(') + 1:body.rindex(')')].split(',')


def get_mweb_descriptor_entries(wallet_rpc):
    """Return active MWEB descriptor entries (legacy dual-SPKM helper).

    New descriptor wallets expose a single account descriptor plus internal
    per-index records. This helper maps the account to 'external' for callers
    that still expect the legacy shape.
    """
    entries = {'external': None, 'internal': None}
    account = get_mweb_account_descriptor(wallet_rpc, private=True)
    if account:
        entries['external'] = account
    internals = get_mweb_internal_descriptors(wallet_rpc)
    if internals:
        entries['internal'] = internals[0]
    return entries


def get_mweb_account_descriptor(wallet_rpc, *, private=False):
    """Return the first ranged MWEB account descriptor from listdescriptors."""
    descs = wallet_rpc.listdescriptors(private)['descriptors']
    for desc in descs:
        body = desc['desc'].split('#')[0]
        if is_mweb_account_desc_body(body):
            return desc
    return None


def get_mweb_account_desc_for_address(wallet_rpc, address):
    """Return the account descriptor string linked to a MWEB address."""
    info = wallet_rpc.getaddressinfo(address)
    assert 'parent_desc' in info, info
    return info['parent_desc']


def get_mweb_account_public_text(wallet_rpc):
    """Return the first MWEB account in its stored public text, with each xprv replaced by its xpub.

    Internal mweb(A_i,B_i,i,acct_cksum) records name their account by the checksum of this text."""
    body = get_mweb_account_descriptor(wallet_rpc, private=True)['desc'].split('#')[0]
    for key in wallet_rpc.gethdkeys(private=True):
        body = body.replace(key['xprv'], key['xpub'])
    return descsum_create(body)


def make_mweb_watchonly_account_descriptor(private_account_desc, public_account_desc):
    """Build importable mweb(scan_priv,spend_pub,*) without mweb_scan_secret.

    private_account_desc provides the scan KEY (kept private).
    public_account_desc provides the neutered spend KEY.
    """
    priv_body = private_account_desc.split('#')[0]
    pub_body = public_account_desc.split('#')[0]
    assert is_mweb_account_desc_body(priv_body), priv_body
    assert is_mweb_account_desc_body(pub_body), pub_body
    scan_priv, _spend_priv = _mweb_desc_parts(priv_body)[:2]
    _scan_pub, spend_pub = _mweb_desc_parts(pub_body)[:2]
    return descsum_create(f"mweb({scan_priv},{spend_pub},*)")


def make_mweb_indexed_watchonly_descriptor(private_account_desc, public_account_desc, index):
    """Build importable mweb(scan_priv,spend_pub,i) from account KEY material."""
    priv_body = private_account_desc.split('#')[0]
    pub_body = public_account_desc.split('#')[0]
    assert is_mweb_account_desc_body(priv_body), priv_body
    assert is_mweb_account_desc_body(pub_body), pub_body
    scan_priv, _spend_priv = _mweb_desc_parts(priv_body)[:2]
    _scan_pub, spend_pub = _mweb_desc_parts(pub_body)[:2]
    return descsum_create(f"mweb({scan_priv},{spend_pub},{int(index)})")


def make_mweb_single_subaddr_descriptor(private_account_desc, spend_pubkey_hex):
    """Build importable LIP two-arg mweb(scan_priv,B_i) for one subaddress."""
    priv_body = private_account_desc.split('#')[0]
    assert is_mweb_account_desc_body(priv_body), priv_body
    scan_priv, _spend = _mweb_desc_parts(priv_body)[:2]
    return descsum_create(f"mweb({scan_priv},{spend_pubkey_hex})")

def neuter_mweb_account_descriptor(wallet_rpc, account_desc):
    """Return a fully-public ranged account form mweb(scan_pub,spend_pub,*).

    Prefer make_mweb_watchonly_account_descriptor for watch-only viewing wallets
    that still need the scan secret in the descriptor string.
    """
    body = account_desc.split('#')[0]
    if is_mweb_account_desc_body(body):
        pub = get_mweb_account_descriptor(wallet_rpc, private=False)
        if pub:
            return pub['desc']
    xpub = wallet_rpc.gethdkeys()[0]['xpub']
    return descsum_create(f"mweb({xpub}/0h/100h/0h,{xpub}/0h/100h/1h,*)")


def get_mweb_internal_descriptor_for_address(wallet_rpc, address):
    """Return the internal descriptor entry for a wallet MWEB address.

    Match on the address's (scan, spend) pubkey pair: stealth indices repeat
    across accounts, so an index-based match could return another account's
    descriptor."""
    info = wallet_rpc.getaddressinfo(address)
    ext_scan, ext_spend = info['scan_pubkey'].lower(), info['spend_pubkey'].lower()
    for entry in get_mweb_internal_descriptors(wallet_rpc):
        scan, spend = _parse_mweb_pubkey_pair(entry['desc'].split('#')[0])
        if spend == ext_spend and scan == ext_scan:
            return entry
    raise AssertionError(f"No internal descriptor found for MWEB address {address}")


def _parse_mweb_pubkey_pair(desc_body):
    """Return (scan_hex, spend_hex) from mweb(A_i,B_i) or mweb(A_i,B_i,i,ck)."""
    parts = _mweb_desc_parts(desc_body)
    if len(parts) == 2:
        return parts[0].lower(), parts[1].lower()
    if len(parts) == 4:
        return parts[0].lower(), parts[1].lower()
    raise ValueError(f"Unexpected MWEB descriptor shape: {desc_body}")


def get_mweb_internal_index_for_address(wallet_rpc, address):
    """Return stealth index i for a wallet MWEB address from its internal descriptor."""
    info = wallet_rpc.getaddressinfo(address)
    ext_scan, ext_spend = info['scan_pubkey'].lower(), info['spend_pubkey'].lower()
    for entry in get_mweb_internal_descriptors(wallet_rpc):
        body = entry['desc'].split('#')[0]
        scan, spend = _parse_mweb_pubkey_pair(body)
        if spend == ext_spend and scan == ext_scan:
            return int(_mweb_desc_parts(body)[2])
    raise AssertionError(f"No internal descriptor found for MWEB address {address}")


def get_mweb_internal_descriptors(wallet_rpc):
    """Return all wallet-internal mweb(A_i,B_i,i,acct_cksum) descriptors."""
    internals = []
    for desc in wallet_rpc.listdescriptors()['descriptors']:
        body = desc['desc'].split('#')[0]
        if is_mweb_internal_desc_body(body):
            internals.append(desc)
    return sorted(internals, key=lambda d: d['desc'])


def list_mweb_account_checksums(wallet_rpc, *, private=False):
    """Return checksums for all MWEB account descriptors in the wallet.

    Prefer checksums embedded in internals (public account form). Fall back to
    public account listing so private KEY material does not change the digest.
    """
    del private  # checksums are always over the public account string
    checksums = set()
    for entry in get_mweb_internal_descriptors(wallet_rpc):
        body = entry['desc'].split('#')[0]
        if is_mweb_internal_desc_body(body):
            checksums.add(_mweb_desc_parts(body)[3])
    if checksums:
        return sorted(checksums)
    for desc in wallet_rpc.listdescriptors(False)['descriptors']:
        body = desc['desc'].split('#')[0]
        if is_mweb_account_desc_body(body) and '#' in desc['desc']:
            checksums.add(desc['desc'].split('#', 1)[1][:8])
    return sorted(checksums)


def get_mweb_account_checksum(wallet_rpc):
    """Return the 8-character checksum linked to persisted internal descriptors."""
    for entry in get_mweb_internal_descriptors(wallet_rpc):
        body = entry['desc'].split('#')[0]
        if is_mweb_internal_desc_body(body):
            return _mweb_desc_parts(body)[3]
    account = get_mweb_account_descriptor(wallet_rpc, private=False)
    if not account:
        return None
    if '#' not in account['desc']:
        return None
    return account['desc'].split('#', 1)[1][:8]


def generate(node, nblocks, maxtries=1000000):
    """Generate blocks using the test node's deterministic mining address."""
    return node.generatetoaddress(
        nblocks=nblocks,
        address=node.get_deterministic_priv_key().address,
        maxtries=maxtries,
        called_by_framework=True,
    )


def generatetoaddress(node, nblocks, address, maxtries=1000000):
    return node.generatetoaddress(
        nblocks=nblocks,
        address=address,
        maxtries=maxtries,
        called_by_framework=True,
    )


def make_utxo(node, amount, confirmed=True, scriptPubKey=DUMMY_P2WPKH_SCRIPT):
    """Create a txout with a given amount and scriptPubKey.

    Mines coins as needed.

    confirmed - txouts created will be confirmed in the blockchain;
                unconfirmed otherwise.

    Returns the 'COutPoint' of the UTXO
    """
    fee = 1 * COIN
    while node.getbalance() < satoshi_round((amount + fee) / COIN):
        generate(node, 100)

    new_addr = node.getnewaddress()
    txid = node.sendtoaddress(new_addr, satoshi_round((amount + fee) / COIN))
    tx1 = node.getrawtransaction(txid, 1)
    txid = int(txid, 16)
    i = None

    for i, txout in enumerate(tx1['vout']):
        if txout['scriptPubKey']['addresses'] == [new_addr]:
            break
    assert i is not None

    tx2 = CTransaction()
    tx2.vin = [CTxIn(COutPoint(txid, i))]
    tx2.vout = [CTxOut(amount, scriptPubKey)]
    tx2.rehash()

    signed_tx = node.signrawtransactionwithwallet(tx2.serialize().hex())

    txid = node.sendrawtransaction(signed_tx['hex'], 0)

    if confirmed:
        mempool_size = len(node.getrawmempool())
        while mempool_size > 0:
            generate(node, 1)
            new_size = len(node.getrawmempool())
            assert new_size < mempool_size
            mempool_size = new_size

    return COutPoint(int(txid, 16), 0)


def setup_mweb_chain(mining_node, test=None):
    """Generates all pre-MWEB blocks, pegs 1 coin into the MWEB,
    then mines the first MWEB block which includes that pegin.

    mining_node - The node to use to generate blocks
    test - Optional BitcoinTestFramework instance; when provided, uses
           generate() + reconnect_mweb_peers() so multi-node tests stay in sync.
    """
    if test is not None:
        test.generate(mining_node, FIRST_MWEB_HEIGHT - 1)
        reconnect_mweb_peers(test)
        mining_node.sendtoaddress(mining_node.getnewaddress(address_type='mweb'), 1)
        test.generate(mining_node, 1)
    else:
        generate(mining_node, FIRST_MWEB_HEIGHT - 1)
        mining_node.sendtoaddress(mining_node.getnewaddress(address_type='mweb'), 1)
        generate(mining_node, 1)


MWEB_FIXTURE_PATH = Path(__file__).resolve().parents[1] / 'data' / 'mweb_fixture.json'
# The first blocks of the fixture chain pay the generator's wallet, which funds the peg-ins.
MWEB_FIXTURE_FUNDING_BLOCKS = 5


def mine_mweb_fixture_pre_chain(test, node, *, mocktime, funding_address):
    """Mine blocks 1 to FIRST_MWEB_HEIGHT - 1 of the fixture chain.

    Mining at a fixed mock time to fixed addresses makes these blocks identical
    on every run, so the fixture file only stores the MWEB blocks."""
    from test_framework.wallet import MiniWallet
    node.setmocktime(mocktime)
    test.generatetoaddress(node, MWEB_FIXTURE_FUNDING_BLOCKS, funding_address, sync_fun=test.no_op)
    test.generatetoaddress(node, FIRST_MWEB_HEIGHT - 1 - MWEB_FIXTURE_FUNDING_BLOCKS, MiniWallet(node).get_address(), sync_fun=test.no_op)


def load_mweb_fixture(test, node):
    """Give a node without a wallet the fixture chain: MWEB active, with MWEB coins.

    Returns the fixture, whose 'txs' are signed transactions valid at its tip.
    Regenerate it with mweb_generate_fixture.py."""
    with open(MWEB_FIXTURE_PATH, encoding='utf8') as f:
        fixture = json.load(f)
    mine_mweb_fixture_pre_chain(test, node, mocktime=fixture['mocktime'], funding_address=fixture['funding_address'])
    assert node.getbestblockhash() == fixture['pre_mweb_tip'], "Pre-MWEB fixture blocks changed; rerun mweb_generate_fixture.py"
    for block in fixture['blocks']:
        assert node.submitblock(block) is None
    assert node.getbestblockhash() == fixture['tip']
    return fixture


def get_hogex_tx(node, block_hash=None):
    """Retrieves the HogEx transaction for the block."""
    block_hash = block_hash or node.getbestblockhash()
    hogex_tx_id = node.getblock(block_hash)['tx'][-1]
    hogex_tx = FromHex(CTransaction(), node.getrawtransaction(hogex_tx_id, False, block_hash))
    hogex_tx.rehash()
    return hogex_tx


def get_hog_addr_txout(node, block_hash=None):
    """Retrieves the HogAddr for a block."""
    return get_hogex_tx(node, block_hash).vout[0]


def get_mweb_header(node, block_hash=None):
    """Retrieves the MWEB header for a block."""
    block_hash = block_hash or node.getbestblockhash()
    best_block = node.getblock(block_hash, 2)
    mweb_json = best_block.get('mweb_header')
    if mweb_json is None and isinstance(best_block.get('mweb'), dict):
        mweb_json = best_block['mweb']
    if mweb_json is None:
        return None

    mweb_header = MWEBHeader()
    mweb_header.from_json(mweb_json)
    return mweb_header


def create_hogex(node, mweb_hash, amount=None):
    """Creates a HogEx transaction that commits to the provided MWEB hash."""
    hogex_tx = get_hogex_tx(node)

    tx = CTransaction()
    tx.vin = [CTxIn(COutPoint(hogex_tx.sha256, 0))]
    tx.vout = [CTxOut(hogex_tx.vout[0].nValue if amount is None else amount, hogaddr_script(mweb_hash.to_byte_arr()))]
    tx.hogex = True
    tx.rehash()
    return tx


def assert_mweb_utxo_scan_stats(wallet_rpc, *, min_examined=1, min_matched=1):
    """Call mwebscanutxoset and assert basic scan success."""
    from test_framework.util import assert_greater_than_or_equal

    stats = wallet_rpc.mwebscanutxoset()
    assert stats['success']
    assert_greater_than_or_equal(stats['examined'], min_examined)
    assert_greater_than_or_equal(stats['matched'], min_matched)
    return stats


def mweb_unspent_output_ids(node, minconf=0):
    """Return the set of spendable MWEB output_ids from listunspent."""
    return {u['output_id'] for u in node.listunspent(minconf) if u.get('output_id')}


def l1_unspent_outpoints(node, minconf=1):
    """Return {(txid, vout)} for L1 UTXOs (entries that expose vout, not output_id)."""
    return {(u['txid'], u['vout']) for u in node.listunspent(minconf)
            if 'vout' in u and not u.get('output_id')}


def decode_wallet_tx(node, txid):
    """Verbose tx JSON for a wallet/mempool tx (MWEB body + vins).

    Prefer getrawtransaction(verbose) over decoderawtransaction: peg-in
    scriptPubKey shapes can fail decoderawtransaction's RPCResult type check
    (missing optional `desc`), while getrawtransaction still returns usable
    ismweb/output_id/vkern fields for assertions.
    """
    try:
        return node.getrawtransaction(txid, True)
    except Exception:
        return node.decoderawtransaction(node.gettransaction(txid)['hex'])


def mweb_vin_output_ids(decoded):
    return {vin['output_id'] for vin in decoded.get('vin', []) if vin.get('ismweb')}


def l1_vin_outpoints(decoded):
    return {(vin['txid'], vin['vout']) for vin in decoded.get('vin', [])
            if not vin.get('ismweb') and 'txid' in vin}


def pegout_payments(decoded):
    """Flatten vkern pegouts as (address_or_None, Decimal value)."""
    from decimal import Decimal
    found = []
    for kern in decoded.get('vkern', []):
        for peg in kern.get('pegout', []):
            spk = peg.get('scriptPubKey', {})
            addr = spk.get('address')
            found.append((addr, Decimal(str(peg['value']))))
    return found


def assert_exact_mweb_inputs(decoded, expected_oids):
    from test_framework.util import assert_equal
    assert_equal(mweb_vin_output_ids(decoded), set(expected_oids))


def assert_l1_inputs_include(decoded, expected_outpoints):
    actual = l1_vin_outpoints(decoded)
    missing = set(expected_outpoints) - actual
    assert not missing, f"missing L1 vin(s) {missing}; have {actual}"


def assert_pegout_payments_include(decoded, expected):
    """expected: iterable of (address, amount). Each must appear in vkern pegouts."""
    payments = pegout_payments(decoded)
    remaining = list(payments)
    for addr, amount in expected:
        match = None
        for i, (a, v) in enumerate(remaining):
            if a == addr and v == amount:
                match = i
                break
        assert match is not None, f"missing peg-out {addr}={amount}; have {payments}"
        remaining.pop(match)


def assert_mweb_oids_spent(node, spent_oids, minconf=0):
    remaining = mweb_unspent_output_ids(node, minconf)
    still = set(spent_oids) & remaining
    assert not still, f"expected spent output_ids still unspent: {still}"
